entries[165568] = { ["name"] = "Invocation of Yu'lon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Agility\nUse: Command an invocation of Yu'lon to strike your target, dealing 191 Nature damage split among them and all nearby enemies. Deals increased damage when striking multiple targets. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[165569] = { ["name"] = "Ward of Envelopment", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Intellect\nUse: Envelop up to 5 allies in the targeted area in shared shields for 10 sec, preventing up to [ 458 * (1 + Versatility)] damage taken by any of them. Damage prevented is increased when affecting multiple allies. (2 Min Cooldown)\nSell Price:" }
entries[165570] = { ["name"] = "Everchill Anchor", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Strength\nEquip: Your damaging melee abilities apply Everchill, dealing 1 Frost damage every 3 sec and reducing movement speed by 2%, stacking up to 10 times. Lasts 12 sec. (750ms cooldown)\nSell Price:" }
entries[165571] = { ["name"] = "Incandescent Sliver", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Intellect\nEquip: While no allies are within 5 yds of you, gain 1 Critical Strike every 2 sec. At 10 applications of this effect, you also gain 4 Mastery. These effects slowly fade when allies are nearby, unless they also bear this item.\nSell Price:" }
entries[165572] = { ["name"] = "Variable Intensity Gigavolt Oscillating Reactor", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Agility\nEquip: Your Critical Strike increases by 3 every 2 sec, capping at ( 3 * 6) Critical Strike for 6 sec, then decreasing and turning off for 6 sec, cycling every 32 sec.\nUse: Maintain the current Oscillation for 6 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[165573] = { ["name"] = "Diamond-Laced Refracting Prism", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength]\nEquip: Every 10 sec, gain an absorb shield for [ 82 * (1 + Versatility)], up to a maximum absorb of [( 82 * (1 + Versatility)) * 5].\nSell Price:" }
entries[165574] = { ["name"] = "Grong's Primal Rage", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Strength\nUse: Enter a primal rage, dealing ( 93 * 5) Physical damage split among nearby enemies over 4 sec. Deals increased damage when striking multiple targets. You cannot move or use abilities during your rage. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[165576] = { ["name"] = "Tidestorm Codex", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Intellect\nUse: Unleash a wave of 6 Tide Elementals that crash into your target, each exploding for 52 Frost damage split among all nearby enemies. Deals increased damage when striking multiple targets. (1.5m cooldown) (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[165577] = { ["name"] = "Bwonsamdi's Bargain", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength]\nEquip: Absorbs up to 2236 damage from an attack that would kill you. When this effect occurs, you instantly heal for 434 and then gain Bwonsamdi's Bargain absorbing healing equal to 60% of the initial damage prevented. May only occur once every 6 min.\nSell Price:" }
