entries[165693] = { ["name"] = "Vantus Rune Technique: Battle of Dazar'alor", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Battle of Dazar'alor.\nCraft a Vantus Rune: Battle of Dazar'alor.\nRequires Kul Tiran Inscription (150)\nSell Price:\nVantus Rune: Battle of Dazar'alor\nUse: Attune yourself to the energies of the targeted Battle of Dazar'alor raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Ultramarine Ink (30), Viridescent Ink (10)" }
entries[165694] = { ["name"] = "Vantus Rune Technique: Battle of Dazar'alor", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Battle of Dazar'alor more efficiently.\nReduces the materials required to craft a Vantus Rune: Battle of Dazar'alor.\nRequires Kul Tiran Inscription (150)\nSell Price:\nVantus Rune: Battle of Dazar'alor\nUse: Attune yourself to the energies of the targeted Battle of Dazar'alor raid boss, increasing your Versatility by 2078 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Light Parchment , Ultramarine Ink (28), Viridescent Ink (8)" }
