entries[166260] = { ["name"] = "Plans: Monel-Hardened Hoofplates", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft Monel-Hardened Hoofplates more effectively.\nGreatly reduce the materials required to create a set of Monel-Hardened Hoofplates.\nRequires Kul Tiran Blacksmithing (95)\nSell Price:\nMonel-Hardened Hoofplates\nUse: Place hoofplates onto your mount, increasing speed while mounted in Kul Tiras or Zandalar by 20% for 2 hrs.\n\nThe effect's duration is quadrupled for blacksmiths.\nRequires Monelite Ore (15), Durable Flux (2)" }
entries[166263] = { ["name"] = "Recipe: Sanguinated Feast", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Sanguinated Feast more effectively.\nPrepare Sanguinated Feasts more efficiently, using fewer materials.\nRequires Kul Tiran Cooking (1)\nRequires Tortollan Seekers\n- Exalted\nSell Price:\nSanguinated Feast\nUse: Set out a Sanguinated Feast to feed up to 35 people in your raid or party!\n\nRestores 38462 health and 23077 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 46 in a stat for 1 hour.\nSell Price:\nRequires Stringy Loins (18), Meaty Haunch (18), Fresh Potato (28), Aromatic Fish Oil (17), Sanguicell (17)" }
entries[166264] = { ["name"] = "Recipe: Sanguinated Feast", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Sanguinated Feast more effectively.\nPrepare Sanguinated Feasts more efficiently, using significantly fewer materials.\nRequires Kul Tiran Cooking (1)\nSell Price:\nSanguinated Feast\nUse: Set out a Sanguinated Feast to feed up to 35 people in your raid or party!\n\nRestores 38462 health and 23077 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 46 in a stat for 1 hour.\nSell Price:\nRequires Stringy Loins (15), Meaty Haunch (15), Fresh Potato (25), Aromatic Fish Oil (15), Sanguicell (15)" }
