entries[166276] = { ["name"] = "Schematic: Unstable Temporal Time Shifter", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Unstable Temporal Time Shifter more efficiently.\nGreatly reduce the materials required to craft an Unstable Temporal Time Shifter.\nRequires Kul Tiran Engineering (1)\nSell Price:\nUnstable Temporal Time Shifter\nUse: Reverses the flow of time on a target that recently died, restoring them to life with 60% health and 20% mana. Castable in combat.\n\nChance to backfire, fast forwarding the flow of time on a target resulting in a loss of vitality.\n\nCannot be used by players higher than level 50. (10 Min Cooldown)\nRequires Kul Tiran Engineering (85)\n\"While this device can certainly bring the dead back to life, it may also bring the living to the brink of death.\"\nRequires Monelite Ore (8), Storm Silver Ore (6), Insulated Wiring (15)" }
entries[166277] = { ["name"] = "Schematic: Unstable Temporal Time Shifter", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Unstable Temporal Time Shifter more efficiently.\nReduce the materials required to craft an Unstable Temporal Time Shifter.\nRequires Kul Tiran Engineering (1)\nRequires Proudmoore Admiralty\n- Exalted\nSell Price:\nUnstable Temporal Time Shifter\nUse: Reverses the flow of time on a target that recently died, restoring them to life with 60% health and 20% mana. Castable in combat.\n\nChance to backfire, fast forwarding the flow of time on a target resulting in a loss of vitality.\n\nCannot be used by players higher than level 50. (10 Min Cooldown)\nRequires Kul Tiran Engineering (85)\n\"While this device can certainly bring the dead back to life, it may also bring the living to the brink of death.\"\nRequires Monelite Ore (10), Storm Silver Ore (7), Insulated Wiring (18)" }
