entries[166422] = { ["name"] = "Recipe: Silas' Sphere of Transmutation", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Silas' Sphere of Transmutation.\nCraft Silas' Sphere of Transmutation.\nRequires Kul Tiran Alchemy (150)\nSell Price:\nSilas' Sphere of Transmutation\nBinds when picked up\nUnique\nHighlights and allows the player to interact with various cauldrons on Kul Tiras and Zandalar.\nUse: Concentrate on the sphere to transmute it into another object for 1 hour.\nRequires Kul Tiran Alchemy (150)\n\"The sphere's surface swirls and shifts, showing different images for brief moments, never long enough to see what they actually are.\"\nRequires Purposefully Potent Potion , Sphere of Sangaurum , Extremely Precise Vial , Sly Rogue's Decanter , Anchor Weed (50), Mystical Cauldron , Expulsom (10)" }
entries[166428] = { ["name"] = "Blackpaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses Blackpaw.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Blackpaw was just hibernating, minding his own business, and then suddenly there was a warfront.\"\nDrop:\nAgathe Wyrmwood\nZone:\nDarkshore\n\nDrop:\nZone:\nDarkshore" }
entries[166432] = { ["name"] = "Ashenvale Chimaera", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses an Ashenvale Chimaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Ashenvale chimaeras were used frequently by the Kaldorei to decimate structures in battles against the humans, orcs, and undead.\"\nDrop:\nAlash'anir\nZone:\nDarkshore" }
entries[166433] = { ["name"] = "Frightened Kodo", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Nothing frightens a kodo like seeing a bear with antlers.\"\nDrop:\nZone:\nDarkshore" }
entries[166434] = { ["name"] = "Captured Umber Nightsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Nightsabers are an integral part of the Kaldorei's army, serving as both mount and assault weapon in one.\"\nDrop:\nMoxo the Beheader\nZone:\nDarkshore\n\nDrop:\nAthil Dewfire\nZone:\nDarkshore" }
entries[166435] = { ["name"] = "Kaldorei Nightsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The connection between a nightsaber and its hunter or huntress is nearly inseparable.\"\nDrop:\nCroz Bloodrage\nZone:\nDarkshore\n\nDrop:\nShadowclaw\nZone:\nDarkshore" }
entries[166436] = { ["name"] = "Sandy Nightsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Sandy Nightsaber.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nComplete the Battle for Darkshore on Heroic Difficulty.\n\n\"A rare color for a nightsaber, and rarely seen, they are prized amongst huntresses.\"\nVendor:\nProvisioner Stoutforge\nZone:\nTiragarde Sound\nCost:\n350\n\nVendor:\nProvisioner Mukra\nZone:\nZuldazar\nCost:\n350" }
