entries[166463] = { ["name"] = "Priestess' Moonsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Once these elegant cats were only given to high-ranking priestesses of Elune, but now they ride into battle with all manner of champion, in the service of vengeance.\"\nVendor:\nProvisioner Stoutforge\nZone:\nTiragarde Sound\nCost:\n750" }
