entries[166467] = { ["name"] = "Island Thunderscale", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"One of the larger native dragon species on Azeroth, this subspecies subsists almost entirely on fish. And fishermen.\"\nDrop:\nIsland Expeditions" }
