entries[166773] = { ["name"] = "Goblin Explosives", ["text"] = "Darkshore\nQuest Item\nUnique\n\"Who in their right mind thought it was a good idea to leave explosives around?\"" }
entries[166774] = { ["name"] = "Hogrus, Swine of Good Fortune", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Hogrus was first seen by Emperor Shaohao on the third day of his meditation, and is considered by the Pandaren to be a sign of good fortune to come to those who take action.\"\nIn-Game Shop" }
entries[166775] = { ["name"] = "Vulpine Familiar", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A fiercely intelligent and curious species, these fox-like creatures have travelled the Great Dark Beyond and found their way to Azeroth. Drawn to Azeroth's champions, they seek adventure and companionship.\"\nIn-Game Shop" }
entries[166776] = { ["name"] = "Sylverian Dreamer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"An artist in the magical city of Dalaran fell asleep on her brush, and dreamed of painting a beautiful feathered dragon. Her artwork leapt from the page, and when she awoke, she found it sleeping gently beside her.\"\nIn-Game Shop" }
entries[166777] = { ["name"] = "Lion's Pride Firework", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Set off a firework on the fresh corpse of a Horde player. (3 Sec Cooldown)\nSell Price:" }
