entries[166803] = { ["name"] = "Umber Nightsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Nightsabers are an integral part of the Kaldorei's army, serving as both mount and assault weapon in one.\"\nDrop:\nMoxo the Beheader\nZone:\nDarkshore\n\nDrop:\nAthil Dewfire\nZone:\nDarkshore" }
entries[166804] = { ["name"] = "Boralus Blood Sausage", ["text"] = "Use: Restores 38462 health and 23077 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 39 in a stat for 1 hour.\nSell Price:" }
entries[166805] = { ["name"] = "Blood-Soaked Invitation", ["text"] = "Binds when picked up\nUnique\nUse: Gain access to the Brawler's Guild for all characters for your Warband.\nSell Price:" }
entries[166806] = { ["name"] = "Recipe: Boralus Blood Sausage", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft Boralus Blood Sausage more effectively.\nPrepare more Boralus Blood Sausage\nin each batch.\nRequires Kul Tiran Cooking (1)\nRequires Tortollan Seekers\n- Exalted\nSell Price:\nBoralus Blood Sausage\nUse: Restores 38462 health and 23077 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 39 in a stat for 1 hour.\nSell Price:\nRequires Thick Paleo Steak (5), Foosaka (3), Aromatic Fish Oil (2), Sanguicell (5)" }
entries[166807] = { ["name"] = "Recipe: Boralus Blood Sausage", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft Boralus Blood Sausage more effectively.\nYou don't waste a single ingredient, preparing much more Boralus Blood Sausage in each batch.\nRequires Kul Tiran Cooking (1)\nSell Price:\nBoralus Blood Sausage\nUse: Restores 38462 health and 23077 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 39 in a stat for 1 hour.\nSell Price:\nRequires Thick Paleo Steak (5), Foosaka (3), Aromatic Fish Oil (2), Sanguicell (5)" }
